  <style>
    *{box-sizing:border-box}body{margin:0;background:#071321;color:#eaf7ff;font-family:Montserrat,sans-serif}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:max(24px,env(safe-area-inset-top)) max(5%,env(safe-area-inset-right)) 24px max(5%,env(safe-area-inset-left));border-bottom:1px solid #24587b;background:#091b2c}.top h1{margin:0;color:#ed2031;font:2.5rem Bangers,sans-serif;letter-spacing:.06em;text-shadow:2px 2px #fff}.top button{min-height:44px;padding:10px 14px;border:1px solid #6389a3;background:transparent;color:#d8edf7;cursor:pointer;font-weight:800}.wrap{width:min(1180px,90%);margin:38px auto}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:28px}.stat{padding:22px;border:1px solid #24587b;background:#0b2136;box-shadow:4px 4px #ed2031}.stat b{display:block;color:#fff;font:2.4rem Bangers,sans-serif}.stat span{color:#86b7d3;font-size:.65rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.table-wrap{max-width:100%;overflow:auto;border:1px solid #24587b;-webkit-overflow-scrolling:touch}table{width:100%;min-width:570px;border-collapse:collapse;background:#0a1c2d;font-size:.76rem}th,td{padding:14px;text-align:left;border-bottom:1px solid #173b54;vertical-align:top}th{color:#86cfee;background:#0d2940;font-size:.62rem;letter-spacing:.09em;text-transform:uppercase}.yes{color:#7de1a5;font-weight:800}.no{color:#ff8993;font-weight:800}a{color:#7ed8ff}.empty{padding:40px;text-align:center;color:#8eb2c6}.pagination{margin-top:22px;color:#fff;overflow:auto}.pagination nav>div:first-child{display:none}.pagination nav>div:last-child>div:first-child{display:none}.pagination svg{width:18px}.pagination a,.pagination span{display:inline-flex;padding:8px 11px;border:1px solid #24587b;text-decoration:none}.pagination span[aria-current="page"] span{background:#ed2031}@media(max-width:700px){.top{align-items:flex-start;padding-left:4%;padding-right:4%}.top h1{font-size:1.75rem;line-height:.9}.top button{