<body><header class="top"><h1>CENTRO DE MISIÓN · CRIS</h1><form method="POST" action="{{ route('rsvp.logout') }}">@csrf<button type="submit">CERRAR SISTEMA</button></form></header><main class="wrap"><section class="stats"><article class="stat"><b>{{ $confirmedHosts }}</b><span>Héroes confirmados</span></article><article class="stat"><b>{{ $confirmedGuests }}</b><span>Acompañantes</span></article><article class="stat"><b>{{ $confirmedHosts + $confirmedGuests }}</b><span>Personas en la misión</span></article></section><section class="table-wrap">@if($rsvps->isEmpty())<div class="empty">Aún no hay transmisiones recibidas.</div>@else<table><thead><tr><th>Fecha</th><th>Nombre</th><th>Respuesta</th><th>Acomp.</th><th>Teléfono</th><th class="hide-mobile">Mensaje</th></tr></thead><tbody>@foreach($rsvps as $rsvp)<tr><td>{{ $rsvp->created_at->format('d/m/Y H:i') }}</td><td><strong>{{ $rsvp->name }}</strong></td><td class="{{ $rsvp->attending ? 'yes' : 'no' }}">{{ $rsvp->attending ? 'Asistirá' : 'No asistirá' }}</td><td>{{ $rsvp->attending ? $rsvp->guests : '—' }}</td><td>{{ $rsvp->phone ?: '—' }}</td><td class="hide-mobile">{{ $rsvp->message ?: '—' }}</td></tr>@endforeach</tbody></table>@endif</section><div class="pagination">{{ $rsvps->links() }}</div></main></body>
